type agreementPendingCommentCodeField struct {
	OriginalField, ProjectedCodeOwner int
	OriginalSpan, ProjectedSpan       graph.Span
	ProjectedCode                     agreementNativeOwnerCode
	Target                            string
}

type agreementPendingCommentCodeObservation struct {
	Body, HTML                                        string
	Page                                              agreementHTML
	Diagnostics                                       []render.Diagnostic
	Findings                                          []judge.Finding
	Failures                                          []agreementFailure
	Native                                            agreementNativeOwnerSource
	Check                                             agreementNativeCheckSource
	Tree                                              agreementNativeProseAddressTree
	Cut                                               agreementRemovedCommentDiagnosticReading
	Targets                                           []string
	Plain, PageWindows, ProjectedPlain, ProjectedPage []agreementNativeCodeWindow
	WindowsValid                                      [4]bool
}

func agreementPendingCommentCodeObserve(t *testing.T, body string) agreementPendingCommentCodeObservation {
	t.Helper()
	raw, page, failures := agreementProseP0Failures(t, body)
	native := agreementNativeOwnerReading(body)
	check := agreementNativeCheckReading(body, native)
	cut := agreementCommentCutP0Reading(body)
	root := agreementAttributionRoot(t)
	agreementWrite(t, root, "Notes/Reading.md", agreementEnvelope(t, body))
	findings, err := agreementPublicCheck(t, root)
	if err != nil {
		t.Fatal("readonly public Check setup", err)
	}
	r := agreementPendingCommentCodeObservation{Body: body, HTML: raw.HTML, Page: page, Diagnostics: raw.Diagnostics,
		Findings: findings, Failures: failures, Native: native, Check: check, Cut: cut,
		Tree: agreementNativeProseAddressTreeReading(body, nil), Targets: judge.LinkTargets(body)}
	r.Plain, r.WindowsValid[0] = agreementNativeCodeWindows(body, agreementFootnoteGrammar)
	r.PageWindows, r.WindowsValid[1] = agreementNativeCodeWindows(body, agreementExclusiveCodeGrammar)
	r.ProjectedPlain, r.WindowsValid[2] = agreementNativeCodeWindows(cut.Projected, agreementFootnoteGrammar)
	r.ProjectedPage, r.WindowsValid[3] = agreementNativeCodeWindows(cut.Projected, agreementExclusiveCodeGrammar)
	return r
}

func agreementPendingCommentCodeFields(t *testing.T, r *agreementPendingCommentCodeObservation, target string) []agreementPendingCommentCodeField {
	t.Helper()
	fields := make([]agreementPendingCommentCodeField, 0)
	if !slices.Equal(r.Check.Targets, r.Targets) || !r.Cut.Valid {
		return fields
	}
	if len(r.Cut.Projected) != len(r.Cut.Positions) {
		t.Fatal("readonly projection map length")
	}
	reverse := map[int]int{}
	for i, at := range r.Cut.Positions {
		if at < 0 || at >= len(r.Body) || r.Body[at] != r.Cut.Projected[i] || i > 0 && at <= r.Cut.Positions[i-1] {
			t.Fatal("readonly whole retained-byte map")
		}
		reverse[at] = i
	}
	for fi, f := range r.Check.Fields {
		if f.Code || f.Comment || f.Escaped || f.DefinitionOwner >= 0 || f.CodeOwner >= 0 || !slices.Equal(f.Targets, []string{target}) || f.Word != "[["+target+"]]" {
			continue
		}
		if f.Span.Start < 0 || f.Span.Stop > len(r.Body) || f.Span.Start >= f.Span.Stop || r.Body[f.Span.Start:f.Span.Stop] != f.Word {
			t.Fatal("readonly whole physical field bytes")
		}
		start, ok := reverse[f.Span.Start]
		if !ok {
			continue
		}
		contiguous := true
		for at := f.Span.Start; at < f.Span.Stop; at++ {
			i, kept := reverse[at]
			if !kept || i != start+at-f.Span.Start {
				contiguous = false
			}
		}
		if !contiguous {
			continue
		}
		stop := start + f.Span.Stop - f.Span.Start
		if r.Cut.Projected[start:stop] != f.Word {
			t.Fatal("readonly projected complete field bytes")
		}
		owner, count := -1, 0
		for ci, c := range r.Cut.ProjectedNative.Code {
			if c.Span.Start <= start && stop <= c.Span.Stop {
				owner, count = ci, count+1
			}
		}
		if count != 1 {
			continue
		}
		fields = append(fields, agreementPendingCommentCodeField{OriginalField: fi, OriginalSpan: f.Span,
			ProjectedSpan: graph.Span{Start: start, Stop: stop}, ProjectedCodeOwner: owner,
			ProjectedCode: r.Cut.ProjectedNative.Code[owner], Target: target})
	}
	return fields
}

// A renamed physical field owns every change in the two public observations.
// Comments retain their byte map and both original grammars retain their roles.
func agreementCommentCodeOwnedControl(before, after *agreementPendingCommentCodeObservation, fields []agreementPendingCommentCodeField, selected *agreementFailure) bool {
	if before == nil || after == nil || selected == nil || len(fields) == 0 || selected.Property != "P1" || selected.Identity != "citation-occurrences" || selected.Direction != "judge-only" || selected.Multiplicity < len(fields) || selected.Tuple.Target == "" || selected.Tuple.SourceRole != "" || selected.Tuple.Section != "" || selected.Tuple.State != "" || selected.Fragment != "" || selected.Cut != "" || selected.PagePresent || selected.JudgeAccepted || selected.ExcerptFound {
		return false
	}
	old := selected.Tuple.Target
	replacement := strings.Repeat("q", len(old))
	if strings.Contains(before.Body, "q") || !before.Cut.Valid || !after.Cut.Valid || before.WindowsValid != [4]bool{true, true, true, true} || after.WindowsValid != before.WindowsValid {
		return false
	}
	if !cmp.Equal(before.Native, after.Native) || !cmp.Equal(before.Tree, after.Tree) || !cmp.Equal(before.Page, after.Page) || !cmp.Equal(before.Diagnostics, after.Diagnostics) {
		return false
	}
	htmlFields := make([]agreementCommentCodeHTMLField, 0, len(fields))
	changed := []byte(before.Body)
	projected := []byte(before.Cut.Projected)
	seen := map[int]bool{}
	for _, owner := range fields {
		if owner.Target != old || owner.OriginalField < 0 || owner.OriginalField >= len(before.Check.Fields) || seen[owner.OriginalField] {
			return false
		}
		seen[owner.OriginalField] = true
		f := before.Check.Fields[owner.OriginalField]
		a, b := f.Span.Start, f.Span.Stop
		c, d := owner.ProjectedSpan.Start, owner.ProjectedSpan.Stop
		if f.Code || f.Comment || f.Escaped || f.DefinitionOwner >= 0 || f.CodeOwner >= 0 || f.Span != owner.OriginalSpan || !slices.Equal(f.Targets, []string{old}) || f.Word != "[["+old+"]]" || a < 0 || b > len(before.Body) || c < 0 || d > len(projected) || b-a != d-c || before.Body[a:b] != f.Word || before.Cut.Projected[c:d] != f.Word {
			return false
		}
		for _, code := range before.Native.Code {
			if a < code.Span.Stop && code.Span.Start < b {
				return false
			}
		}
		for _, windows := range [][]agreementNativeCodeWindow{before.Plain, before.PageWindows} {
			for _, code := range windows {
				if a < code.Span.Stop && code.Span.Start < b {
					return false
				}
			}
		}
		line := 3 + strings.Count(before.Body[:a], "\n")
		for i := range before.Findings {
			finding := &before.Findings[i]
			if finding.RuleID == "callout.title_markup" && finding.Line != nil && *finding.Line == line && finding.Target != nil && strings.Contains(*finding.Target, f.Word) {
				return false
			}
		}
		if len(before.Cut.Positions) != len(projected) {
			return false
		}
		for at := a; at < b; at++ {
			if before.Cut.Positions[c+at-a] != at {
				return false
			}
		}
		copy(changed[a+2:b-2], replacement)
		copy(projected[c+2:d-2], replacement)
		htmlFields = append(htmlFields, agreementCommentCodeHTMLField{OriginalSpan: owner.OriginalSpan, ProjectedSpan: owner.ProjectedSpan, Target: old})
	}
	if string(changed) != after.Body || string(projected) != after.Cut.Projected {
		return false
	}
	if !agreementCommentCodeOwnedCheck(&before.Check, &after.Check, fields, false) || !agreementCommentCodeOwnedCheck(&before.Cut.ProjectedCheck, &after.Cut.ProjectedCheck, fields, true) || !slices.Equal(before.Targets, before.Check.Targets) || !slices.Equal(after.Targets, after.Check.Targets) {
		return false
	}
	expectedCut := before.Cut
	expectedCut.Check = after.Check
	expectedCut.Projected = after.Cut.Projected
	expectedCut.ProjectedCheck = after.Cut.ProjectedCheck
	if !cmp.Equal(expectedCut, after.Cut) {
		return false
	}
	for i, windows := range [][]agreementNativeCodeWindow{before.Plain, before.PageWindows, before.ProjectedPlain, before.ProjectedPage} {
		private := [][]agreementNativeCodeWindow{after.Plain, after.PageWindows, after.ProjectedPlain, after.ProjectedPage}[i]
		if !agreementCommentCodeOwnedWindows(before, windows, private, fields, i >= 2) {
			return false
		}
	}
	if !agreementCommentCodeHTMLProjection(before.Body, before.HTML, after.HTML, before.Cut.Projected, before.Cut.Positions, before.ProjectedPage, htmlFields) || !agreementCommentCodeOwnedFindings(before, after, fields) {
		return false
	}
	expected := map[string]int{}
	found := 0
	for i := range before.Failures {
		f := before.Failures[i]
		if agreementSignature(&f) != agreementSignature(selected) {
			expected[agreementSignature(&f)]++
			continue
		}
		found++
		if f.Multiplicity > len(fields) {
			f.Multiplicity -= len(fields)
			expected[agreementSignature(&f)]++
		}
		f = *selected
		f.Tuple.Target = replacement
		f.Multiplicity = len(fields)
		expected[agreementSignature(&f)]++
	}
	return found == 1 && maps.Equal(expected, agreementMixedCurrent(after.Failures))
}

func agreementCommentCodeOwnedCheck(before, after *agreementNativeCheckSource, fields []agreementPendingCommentCodeField, projected bool) bool {
	expected := *before
	expected.Fields = slices.Clone(before.Fields)
	hit := map[int]bool{}
	for _, owner := range fields {
		span := owner.OriginalSpan
		if projected {
			span = owner.ProjectedSpan
		}
		count := 0
		for i := range expected.Fields {
			f := &expected.Fields[i]
			if f.Span != span {
				continue
			}
			if hit[i] || f.Word != "[["+owner.Target+"]]" || !slices.Equal(f.Targets, []string{owner.Target}) {
				return false
			}
			hit[i] = true
			count++
			f.Word = "[[" + strings.Repeat("q", len(owner.Target)) + "]]"
			f.Targets = []string{strings.Repeat("q", len(owner.Target))}
		}
		if count != 1 {
			return false
		}
	}
	expected.Targets = nil
	for _, f := range expected.Fields {
		if !f.Code && !f.Comment && !f.Escaped {
			expected.Targets = append(expected.Targets, f.Targets...)
		}
	}
	return cmp.Equal(expected, *after)
}

func agreementCommentCodeOwnedWindows(before *agreementPendingCommentCodeObservation, windows, private []agreementNativeCodeWindow, fields []agreementPendingCommentCodeField, projected bool) bool {
	if len(windows) != len(private) {
		return false
	}
	source := before.Body
	if projected {
		source = before.Cut.Projected
	}
	old := fields[0].Target
	word := "[[" + old + "]]"
	replacement := strings.Repeat("q", len(old))
	hits := make([]int, len(fields))
	for i, window := range windows {
		a, b := window.Span.Start, window.Span.Stop
		if a < 0 || b > len(source) || a > b || window.Kind != private[i].Kind || window.Span != private[i].Span {
			return false
		}
		sourceSites, textSites := agreementCommentCodeHTMLSites(source[a:b], word), agreementCommentCodeHTMLSites(window.Text, word)
		text := []byte(window.Text)
		for fi, field := range fields {
			span := field.OriginalSpan
			if projected {
				span = field.ProjectedSpan
			}
			if a <= span.Start && span.Stop <= b {
				if len(sourceSites) != len(textSites) || source[span.Start:span.Stop] != word {
					return false
				}
				ordinal := slices.Index(sourceSites, span.Start-a)
				if ordinal < 0 {
					return false
				}
				at := textSites[ordinal] + 2
				copy(text[at:at+len(old)], replacement)
				hits[fi]++
			}
		}
		if string(text) != private[i].Text {
			return false
		}
	}
	for _, count := range hits {
		if projected && count != 1 || !projected && count != 0 {
			return false
		}
	}
	return true
}

func agreementCommentCodeOwnedFingerprint(rule judge.RuleID, path, target string) string {
	var value uint64 = 0xcbf29ce484222325
	for _, part := range []string{string(rule), path, target} {
		for _, b := range []byte(part + "\x1f") {
			value = (value ^ uint64(b)) * 0x100000001b3
		}
	}
	return fmt.Sprintf("v1:%016x", value)
}

func agreementCommentCodeOwnedFindings(before, after *agreementPendingCommentCodeObservation, fields []agreementPendingCommentCodeField) bool {
	old := fields[0].Target
	newTarget := strings.Repeat("q", len(old))
	lines := map[int]int{}
	for _, f := range fields {
		lines[3+strings.Count(before.Body[:f.OriginalSpan.Start], "\n")]++
	}
	expected := slices.Clone(before.Findings)
	for i := range expected {
		f := &expected[i]
		if f.RuleID != "link.broken" || f.Target == nil || *f.Target != old || f.Line == nil || lines[*f.Line] == 0 {
			continue
		}
		if f.Message != "[["+old+"]] resolves to no note" || f.Fingerprint != agreementCommentCodeOwnedFingerprint(f.RuleID, f.Path, old) {
			return false
		}
		lines[*f.Line]--
		target := newTarget
		f.Target = &target
		f.Message = "[[" + newTarget + "]] resolves to no note"
		f.Fingerprint = agreementCommentCodeOwnedFingerprint(f.RuleID, f.Path, newTarget)
	}
	for _, count := range lines {
		if count != 0 {
			return false
		}
	}
	counter := func(findings []judge.Finding) map[string]int {
		r := map[string]int{}
		for i := range findings {
			b, err := json.Marshal(findings[i])
			if err != nil {
				return nil
			}
			r[string(b)]++
		}
		return r
	}
	return maps.Equal(counter(expected), counter(after.Findings))
}

